#' Qualità delle risposte
#'
#' 
#' @param data .
#' @param items Le domande con la stessa scala di risposta poste una dopo
#'   l'altra, per esempio gli item di una scala Likert, nell'ordine in cui
#'   compaiono nel questionario.
#' @param seqPerc Segnale quando il rispondente dà la stessa risposta a item
#'   consecutivi per almeno questa percentuale degli item. Con 100 il segnale
#'   scatta solo per chi ha dato la stessa risposta a tutti gli item.
#' @param missPerc Segnale quando mancano almeno questa percentuale degli
#'   item.
#' @param pairs Coppie di domande che chiedono la stessa informazione, con le
#'   modalità nello stesso ordine. Per ogni rispondente si calcola la distanza
#'   dalla diagonale della matrice di coerenza.
#' @param distMin Distanza minima dalla diagonale della matrice di coerenza
#'   che conta come segnale: 3 corrisponde alle contraddizioni forti, 2
#'   comprende anche le incoerenze da esaminare.
#' @param minSegnali Numero minimo di segnali per comparire nell'elenco dei
#'   rispondenti.
#' @param tuto Se TRUE mostra il pannello con la descrizione dell'analisi.
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$riepilogo} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$rispondenti} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$matrici} \tab \tab \tab \tab \tab an array of images \cr
#'   \code{results$segnaliOV} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$indicatoriOV} \tab \tab \tab \tab \tab an output \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$riepilogo$asDF}
#'
#' \code{as.data.frame(results$riepilogo)}
#'
#' @export
respquality <- function(
    data,
    items = list(),
    seqPerc = 100,
    missPerc = 50,
    pairs,
    distMin = 3,
    minSegnali = 2,
    tuto = TRUE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("respquality requires jmvcore to be installed (restart may be required)")

    if ( ! missing(items)) items <- jmvcore::resolveQuo(jmvcore::enquo(items))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(items), items, NULL))


    options <- respqualityOptions$new(
        items = items,
        seqPerc = seqPerc,
        missPerc = missPerc,
        pairs = pairs,
        distMin = distMin,
        minSegnali = minSegnali,
        tuto = tuto)

    analysis <- respqualityClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

